/**
 * Synthetic raw-trace cases for the five runtimes: invented records shaped after the argument and result
 * shapes the recorded traces hold (TESTING.md: never copy real records). One case is one record, or a
 * call with its result; `expected` is the neutral journal line the case must give (its head with
 * `→ outcome`, then the lines below it) and is absent when the line does not change with this revision.
 * Groups follow the contract's section 11: conversation, built-in tools, skills, runtime-only tools,
 * platform tools, installed and qualified tools.
 */
export type TraceCase =
  | Readonly<{ group: number; kind: "tool"; tool: string; args: Readonly<Record<string, unknown>>; result: unknown; error: string | null; expected?: Readonly<{ head: string; body: readonly string[] }> }>
  | Readonly<{ group: number; kind: "call_only"; tool: string; args: Readonly<Record<string, unknown>> }>
  | Readonly<{ group: number; kind: "result_only"; tool: string; result: unknown }>
  | Readonly<{ group: number; kind: "record"; type: string; text: string }>;

